                                    }`}
                                >
                                    {isInSlip ? <CheckIcon className="w-8 h-8" /> : <PlusIcon className="w-8 h-8" />}
                                </button>
                            </div>

                            {/* History Section */}
                            {isHistoryExpanded && prop.performanceHistory && (
                                <div className="mb-6 bg-black/40 rounded-3xl p-5 border border-white/5 animate-fade-in relative">
