                                                <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase tracking-widest ${h.hit ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'}`}>
                                                    {h.hit ? 'HIT' : 'MISS'}
                                                </span>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {prop.analysis && (
                                <p className="text-[11px] text-zinc-300 italic mb-5 border-l-4 border-amber-500/30 pl-4 leading-relaxed bg-white/5 py-3 rounded-r-xl">
                                    <strong className="text-amber-500 uppercase text-[9px] block mb-1 font-black">AI Reasoning:</strong>
                                    {prop.analysis}
                                </p>
                            )}

                            <div className="flex items-center gap-4">
                                <div className="flex-1 h-2 bg-black rounded-full overflow-hidden border border-white/5">
                                    <div className={`h-full ${isElite ? 'bg-gradient-to-r from-amber-600 to-amber-400' : 'bg-zinc-700'}`} style={{ width: prop.probability }}></div>
                                </div>
                                <div className="flex items-center gap-4">
                                    <span className={`text-[10px] font-black uppercase tracking-widest ${isElite ? 'text-amber-500' : 'text-zinc-600'}`}>{prop.probability} Accuracy Score</span>
                                    {prop.ev && (
                                        <div className="flex items-center gap-1">
                                            <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
                                            <span className="text-[10px] font-black text-green-500 uppercase tracking-tighter">+{prop.ev}% Market Divergence</span>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>
       </div>

       {/* Laboratory Search */}
       <div className="bg-zinc-950 rounded-[2.5rem] border-2 border-dashed border-zinc-900 p-8 shadow-2xl">
           <div className="flex items-center gap-4 mb-8">
                <AnalyticsIcon className="w-7 h-7 text-amber-500" />
                <div>
                    <h3 className="text-sm font-black text-white uppercase tracking-[0.2em]">Matchup Lab</h3>
                    <p className="text-[10px] text-zinc-600 font-black uppercase tracking-widest">Verify Specific Position Divergence</p>
                </div>
           </div>
           <form onSubmit={handleCustomAnalyze} className="flex flex-col md:flex-row gap-4">
               <input 
                  type="text" 
                  placeholder="Player (e.g. Stephen Curry)"
                  value={customPlayer}
                  onChange={(e) => setCustomPlayer(e.target.value)}
                  className="flex-1 bg-black border-2 border-zinc-900 rounded-2xl px-6 py-4 text-sm font-black focus:ring-2 focus:ring-amber-500/50 outline-none text-white transition-all focus:border-amber-500/50"
               />
               <input 
                  type="text" 
                  placeholder="Stat (e.g. 5.5 3PM)"
                  value={customLine}
                  onChange={(e) => setCustomLine(e.target.value)}
                  className="flex-1 bg-black border-2 border-zinc-900 rounded-2xl px-6 py-4 text-sm font-black focus:ring-2 focus:ring-amber-500/50 outline-none text-white transition-all focus:border-amber-500/50"
               />
               <button 
                  type="submit"
                  className="bg-amber-500 hover:bg-amber-400 text-black font-black px-10 py-4 rounded-2xl transition-all shadow-xl shadow-amber-500/10 uppercase tracking-widest active:scale-95"
               >
                  Test Accuracy
               </button>
           </form>
       </div>
    </div>
  );
});

