export const getSchedule = async (sport: string): Promise<Game[]> => {
  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `CRITICAL TASK: Search for ${sport} games occurring TODAY, ${today}. 

  PRIORITY: 
  1. LIVE GAMES (Show current real-time score and quarter).
  2. UPCOMING GAMES (Show official start time and real betting lines).

  Return STRICT JSON:
  { "games": [{ "id": "string", "homeTeam": "string", "awayTeam": "string", "league": "${sport}", "time": "string", "date": "Today", "status": "Scheduled|Live|Finished", "score": "optional string", "odds": { "spread": "string", "moneyline": "string", "total": "string" } }] }`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        tools: [{ googleSearch: {} }],
        temperature: 0.1,
        responseMimeType: 'application/json'
      }
    });
    const data = JSON.parse(response.text || '{}');
    return data.games || [];
  } catch (error) {
    console.error("Schedule Fetch Failed:", error);
    return [];
  }
};

import React, { memo, useState, useMemo } from 'react';
import type { Prediction, OddsFormat, PropBet } from '../types';
import { AnalyticsIcon, PlusIcon, CheckIcon, DoubleCheckIcon } from './Icons';

interface PredictionDisplayProps {
  prediction: Prediction;
  oddsFormat: OddsFormat;
  onAnalyzeProp?: (prop: PropBet) => void;
  pickSlip?: PropBet[];
  onTogglePick?: (prop: PropBet) => void;
  onSearchPlayer?: (player: string) => void;
}

const confidenceStyles: Record<string, { bg: string; text: string; border: string; accent: string; glow: string }> = {
    High: { bg: 'bg-green-950/20', text: 'text-green-400', border: 'border-green-500/30', accent: 'bg-green-500', glow: 'shadow-[0_0_30px_rgba(34,197,94,0.2)]' },
    Medium: { bg: 'bg-amber-950/20', text: 'text-amber-400', border: 'border-amber-500/30', accent: 'bg-amber-500', glow: 'shadow-[0_0_30px_rgba(245,158,11,0.2)]' },
    Low: { bg: 'bg-zinc-900/40', text: 'text-zinc-400', border: 'border-zinc-800', accent: 'bg-zinc-600', glow: 'shadow-none' },
};

export const PredictionDisplay: React.FC<PredictionDisplayProps> = memo(({ prediction, pickSlip = [], onTogglePick, onSearchPlayer }) => {
  const [typeFilter, setTypeFilter] = useState<'All' | 'MORE' | 'LESS'>('All');
  const [expandedHistories, setExpandedHistories] = useState<Set<string>>(new Set());

  const confidenceStyle = confidenceStyles[prediction.confidence] || confidenceStyles['Medium'];
  const probVal = prediction.confidenceScore != null ? Math.round(prediction.confidenceScore * 100) : 0;

  const toggleHistory = (propId: string) => {
    setExpandedHistories(prev => {
        const next = new Set(prev);
        if (next.has(propId)) next.delete(propId);
        else next.add(propId);
        return next;
    });
  };

  const filteredProps = useMemo(() => {
    if (!prediction.props) return [];
    return [...prediction.props]
      .filter(prop => typeFilter === 'All' || prop.type === typeFilter)
      .sort((a, b) => {
          const probA = parseInt(a.probability) || 0;
          const probB = parseInt(b.probability) || 0;
          return probB - probA;
      });
  }, [prediction.props, typeFilter]);

  return (
    <div className="space-y-6 w-full animate-fade-in pb-10">
       {/* High Accuracy Insight Banner */}
       {prediction.matchupHighlight && (
          <div className="bg-zinc-900/40 border border-amber-500/10 px-6 py-4 rounded-[1.5rem] flex items-center gap-4">
             <div className="bg-amber-500/10 p-2 rounded-full border border-amber-500/20">
                <AnalyticsIcon className="w-5 h-5 text-amber-500" />
             </div>
             <div>
                <span className="text-[9px] font-black uppercase tracking-[0.2em] text-amber-500/60 block mb-0.5">Simulated Defensive Edge</span>
                <span className="text-[11px] font-bold text-zinc-300 leading-relaxed italic">"{prediction.matchupHighlight}"</span>
             </div>
          </div>
       )}

       {/* Primary Prediction Engine Result */}
       <div className={`p-8 rounded-[2.5rem] border ${confidenceStyle.border} ${confidenceStyle.bg} backdrop-blur-3xl shadow-2xl relative overflow-hidden`}>
          {/* Probability Dial Overlay (Background) */}
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 opacity-[0.03] pointer-events-none scale-150">
             <svg className="w-96 h-96" viewBox="0 0 100 100">
                <circle cx="50" cy="50" r="45" fill="none" stroke="currentColor" strokeWidth="2" strokeDasharray="282.7" strokeDashoffset={282.7 - (282.7 * (probVal/100))} className={confidenceStyle.text} />
             </svg>
          </div>

          <div className="flex flex-col md:flex-row justify-between items-center gap-10 relative z-10">
             <div className="flex items-center gap-8">
                 <div className="relative group">
                    <div className={`absolute inset-0 rounded-full blur-2xl ${confidenceStyle.accent} opacity-20`}></div>
                    <img 
                        src={`https://avatar.vercel.sh/${encodeURIComponent(prediction.winner)}.png?size=160`}
                        alt={prediction.winner}
                        className={`w-32 h-32 rounded-full border-4 ${confidenceStyle.border} relative z-10 shadow-2xl`}
                    />
                    <div className="absolute -bottom-2 -right-2 bg-green-500 rounded-full p-2 border-4 border-black z-20 shadow-lg">
                        <CheckIcon className="w-5 h-5 text-black" />
                    </div>
                 </div>
                 <div className="space-y-1">
                    <span className="text-[10px] font-black uppercase tracking-[0.4em] text-amber-500/80 block mb-2">Simulated Winner</span>
                    <h2 className="text-4xl md:text-5xl font-black text-white leading-none tracking-tighter uppercase italic">{prediction.winner}</h2>
                    <div className="flex items-center gap-4 mt-4">
                        <div className="flex flex-col">
                            <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Confidence</span>
                            <span className={`text-xl font-black uppercase ${confidenceStyle.text}`}>{prediction.confidence}</span>
                        </div>
                        <div className="w-px h-8 bg-zinc-800 mx-2"></div>
                        <div className="flex flex-col">
                            <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Accuracy</span>
                            <span className="text-xl font-black text-white tabular-nums">{probVal}%</span>
                        </div>
                    </div>
                 </div>
             </div>

             {/* Probability Dial Visualizer */}
             <div className="relative flex items-center justify-center w-36 h-36">
                <svg className="w-full h-full transform -rotate-90" viewBox="0 0 100 100">
                    <circle cx="50" cy="50" r="44" fill="none" stroke="#18181b" strokeWidth="8" />
                    <circle cx="50" cy="50" r="44" fill="none" stroke="currentColor" strokeWidth="8" strokeDasharray="276" strokeDashoffset={276 - (276 * (probVal/100))} className={`${confidenceStyle.text} transition-all duration-1000 ease-out`} />
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className="text-3xl font-black text-white tabular-nums tracking-tighter">{probVal}%</span>
                    <span className="text-[8px] font-black text-zinc-500 uppercase tracking-widest">Simulated</span>
                </div>
             </div>
          </div>

          {/* Analysis Snippet */}
          <div className="mt-10 pt-8 border-t border-white/5">
              <div className="flex items-start gap-4">
                  <div className="p-1 bg-amber-500/10 rounded-lg">
                      <DoubleCheckIcon className="w-5 h-5 text-amber-500" />
                  </div>
                  <p className="text-zinc-200 text-base md:text-lg leading-relaxed font-medium italic opacity-90">
                    "{prediction.analysis}"
                  </p>
              </div>

              {prediction.simulatedScenarios && (
                  <div className="mt-6 grid grid-cols-3 gap-2">
                      <div className="bg-black/40 p-3 rounded-2xl border border-white/5 flex flex-col items-center">
                          <span className="text-[8px] font-black text-zinc-600 uppercase tracking-widest">Scenarios</span>
                          <span className="text-xs font-black text-zinc-300">179/179</span>
                      </div>
                      <div className="bg-black/40 p-3 rounded-2xl border border-white/5 flex flex-col items-center">
                          <span className="text-[8px] font-black text-zinc-600 uppercase tracking-widest">Win Count</span>
                          <span className="text-xs font-black text-green-500">{prediction.simulatedScenarios.wins} Hits</span>
                      </div>
                      <div className="bg-black/40 p-3 rounded-2xl border border-white/5 flex flex-col items-center">
                          <span className="text-[8px] font-black text-zinc-600 uppercase tracking-widest">Avg Margin</span>
                          <span className="text-xs font-black text-amber-500">{prediction.simulatedScenarios.avgMargin}</span>
                      </div>
                  </div>
              )}
          </div>
       </div>

       {/* Prop Market Breakdown */}
       <div className="space-y-6">
            <div className="flex items-center justify-between px-2">
                 <div className="flex items-center gap-3">
                    <div className="w-1.5 h-1.5 bg-amber-500 rounded-full animate-pulse"></div>
                    <h3 className="text-[11px] font-black text-zinc-500 uppercase tracking-[0.4em]">
                        High Fidelity Player Props
                    </h3>
                 </div>

                 <div className="flex items-center gap-1.5 bg-zinc-900/50 p-1 rounded-xl border border-zinc-800">
                    {['All', 'MORE', 'LESS'].map(filter => (
                        <button 
                            key={filter}
                            onClick={() => setTypeFilter(filter as any)} 
                            className={`px-4 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${
                                typeFilter === filter 
                                    ? 'bg-zinc-800 text-white shadow-lg' : 'text-zinc-600 hover:text-zinc-400'
                            }`}
                        >
                            {filter}
                        </button>
                    ))}
                 </div>
            </div>

            <div className="grid gap-4">
                {filteredProps.map((prop, index) => {
                    const isInSlip = pickSlip.some(p => p.player === prop.player && p.stat === prop.stat);
                    const probInt = parseInt(prop.probability) || 0;
                    const isHighProb = probInt >= 75;
                    const propId = `prop-${prop.player}-${index}`;
                    const isExpanded = expandedHistories.has(propId);

                    return (
                        <div 
                            key={index} 
                            className={`group relative bg-zinc-950/80 rounded-[2rem] border transition-all duration-500 p-6 ${
