                            <div className="mt-6 bg-black/30 rounded-2xl border border-white/5 p-4">
                                <div className="flex items-center justify-between mb-3 px-1">
                                    <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">Market Comparison</span>
                                    <span className="text-[8px] font-bold text-amber-500/50 uppercase">Simulated Odds</span>
                                </div>
                                <div className="grid grid-cols-3 gap-2">
                                    {prop.lineComparison?.map((line, lIdx) => {
                                        const isBest = line.book === bestBook;
                                        return (
                                            <div key={lIdx} className={`p-3 rounded-xl border flex flex-col items-center justify-center gap-1 transition-all ${
                                                isBest ? 'bg-amber-500/10 border-amber-500/50 shadow-[0_0_15px_rgba(245,158,11,0.1)]' : 'bg-zinc-900/50 border-zinc-800'
                                            }`}>
                                                <span className={`text-[8px] font-black uppercase ${isBest ? 'text-amber-500' : 'text-zinc-600'}`}>{line.book}</span>
                                                <span className="text-sm font-black text-white">{line.odds}</span>
                                                {isBest && <span className="text-[7px] font-black text-amber-500 uppercase tracking-tighter">Best Value</span>}
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>

                            {/* Analysis Toggle */}
                            <div className="mt-6 flex flex-col gap-3">
                                <button 
                                    onClick={() => toggleHistory(propId)}
                                    className="text-[9px] font-black text-zinc-500 hover:text-amber-500 uppercase tracking-widest flex items-center gap-2 w-fit transition-colors"
                                >
                                    <AnalyticsIcon className="w-3.5 h-3.5" />
                                    {isExpanded ? 'Hide Data Stream' : 'View Historical Hit Rate'}
                                </button>

                                {isExpanded && prop.performanceHistory && (
                                    <div className="bg-black/50 rounded-2xl p-4 border border-white/5 animate-fade-in">
                                        <div className="grid grid-cols-3 gap-3">
                                            {prop.performanceHistory.map((h, i) => (
                                                <div key={i} className="bg-zinc-900/50 p-3 rounded-xl border border-white/5 text-center">
                                                    <div className="text-[7px] font-black text-zinc-600 uppercase mb-1 truncate">vs {h.opponent}</div>
                                                    <div className={`text-lg font-black tabular-nums ${h.hit ? 'text-green-500' : 'text-rose-500'}`}>
                                                        {h.actualValue}
                                                    </div>
                                                    <div className={`text-[7px] font-black mt-1 uppercase ${h.hit ? 'text-green-500/60' : 'text-rose-500/60'}`}>
                                                        {h.hit ? 'HIT' : 'MISS'}
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}

                                {prop.analysis && (
                                    <p className="text-[11px] text-zinc-400 leading-relaxed italic border-l-2 border-amber-500/20 pl-4 py-1">
                                        {prop.analysis}
                                    </p>
                                )}
                            </div>

                            {/* Probability Gauge */}
                            <div className="mt-5 flex items-center gap-4">
                                <div className="flex-1 h-1.5 bg-zinc-900 rounded-full overflow-hidden border border-white/5">
                                    <div className={`h-full ${isHighProb ? 'bg-green-500' : 'bg-amber-500'}`} style={{ width: prop.probability }}></div>
                                </div>
                                {prop.ev && (
                                    <div className="text-[9px] font-black text-green-500 uppercase tracking-tighter">
                                        +{prop.ev}% Market Edge
                                    </div>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>
       </div>

       {/* Stat Comparison Section */}
       {prediction.statComparison && prediction.statComparison.length > 0 && (
         <div className="mt-12 space-y-6">
            <div className="flex items-center gap-3 px-2">
                <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse"></div>
                <h3 className="text-[11px] font-black text-zinc-500 uppercase tracking-[0.4em]">
                    Engine Data Stream: Stat Matrix
                </h3>
            </div>

            <div className="bg-zinc-950/50 rounded-[2.5rem] border border-zinc-900 overflow-hidden shadow-2xl backdrop-blur-3xl">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-zinc-900/50 border-b border-zinc-800">
                            <th className="px-6 py-4 text-[9px] font-black text-zinc-500 uppercase tracking-widest">Category</th>
                            <th className="px-6 py-4 text-[9px] font-black text-zinc-500 uppercase tracking-widest text-center">Home</th>
                            <th className="px-6 py-4 text-[9px] font-black text-zinc-500 uppercase tracking-widest text-center">Away</th>
                            <th className="px-6 py-4 text-[9px] font-black text-zinc-500 uppercase tracking-widest text-right">Advantage</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-white/5">
                        {prediction.statComparison.map((stat, sIdx) => (
                            <tr key={sIdx} className="hover:bg-white/[0.02] transition-colors group">
                                <td className="px-6 py-4">
                                    <span className="text-xs font-bold text-zinc-300 group-hover:text-white transition-colors uppercase tracking-tight">
                                        {stat.statName}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-center">
                                    <span className={`text-sm font-black tabular-nums ${stat.advantage === 'Home' ? 'text-green-400' : 'text-zinc-500'}`}>
                                        {stat.homeValue}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-center">
                                    <span className={`text-sm font-black tabular-nums ${stat.advantage === 'Away' ? 'text-green-400' : 'text-zinc-500'}`}>
                                        {stat.awayValue}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-tighter border transition-all ${
                                        stat.advantage === 'Push' 
                                            ? 'bg-zinc-800 border-zinc-700 text-zinc-400' 
                                            : 'bg-green-500/10 border-green-500/30 text-green-400 shadow-[0_0_10px_rgba(34,197,94,0.1)]'
                                    }`}>
                                        {stat.advantage === 'Push' ? 'Neutral' : `${stat.advantage} Edge`}
                                    </span>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
         </div>
       )}

       {/* Simulation Lab Footnote */}
       <div className="text-center pt-8">
            <p className="text-[9px] font-bold text-zinc-800 uppercase tracking-[0.5em] animate-pulse">
                Pro-N-Os High Fidelity Signal Engine
            </p>
       </div>
    </div>
  );
});
